CommonData.BannerCustomCSS:
/* LAST UPDATED: 2024-09-05 */
/* UPDATE HERE AND IN a24-rudderstack/onetrust/banner-custom-css.css */

/* BANNER ***********************************/
/* hide floating button */
#ot-sdk-btn-floating {
    display: none !important;
}

/* containers */
#onetrust-banner-sdk:focus {
    outline-width: 1px;
    outline-offset: 0px;
}

#onetrust-banner-sdk.otFloatingRoundedCorner {
    border-radius: 0;
    bottom: 0 !important;
    right: 0 !important;
    left: auto !important;
    box-shadow:
        2.8px -2.8px 2.2px rgba(0, 0, 0, 0.02),
        6.7px -6.7px 5.3px rgba(0, 0, 0, 0.028),
        12.5px -12.5px 10px rgba(0, 0, 0, 0.035),
        22.3px -22.3px 17.9px rgba(0, 0, 0, 0.042),
        41.8px -41.8px 33.4px rgba(0, 0, 0, 0.05),
        100px -100px 80px rgba(0, 0, 0, 0.07);
}

@media only screen and (min-width: 426px) and (max-width: 896px) {
    #onetrust-banner-sdk.otFloatingRoundedCorner {
        width: 100% !important;
        max-width: 100% !important;
    }
}

@media only screen and (max-width: 425px) {
    #onetrust-banner-sdk.otFloatingRoundedCorner {
        width: 100% !important;
        max-width: 100% !important;
    }
}

#onetrust-banner-sdk.ot-wo-title #onetrust-group-container {
    margin-top: 0 !important;
}

/* button group */
#onetrust-button-group-parent {
    margin-top: 10px !important;
}

#onetrust-button-group-parent #onetrust-button-group>button:last-child {
    margin-bottom: 0 !important;
}

/* buttons */
#onetrust-banner-sdk .ot-sdk-button,
#onetrust-banner-sdk button,
#onetrust-pc-sdk .ot-sdk-button,
#onetrust-pc-sdk button,
#onetrust-banner-sdk #onetrust-accept-btn-handler,
#onetrust-banner-sdk #onetrust-reject-all-handler,
#onetrust-banner-sdk #onetrust-pc-btn-handler,
#ot-sdk-cookie-policy .ot-sdk-button,
#ot-sdk-cookie-policy button {
    letter-spacing: 0 !important;
    text-transform: uppercase !important;
    font-weight: bold !important;
    border-radius: 0 !important;
    font-size: 1em !important;
}

#onetrust-banner-sdk #onetrust-pc-btn-handler {
    border: 1px solid currentColor !important;
    text-decoration: none !important;
}

/* paragraph text */
#onetrust-banner-sdk #onetrust-policy-text,
#onetrust-banner-sdk .ot-b-addl-desc {
    line-height: 1.2 !important;
}

#onetrust-banner-sdk #onetrust-policy-text {
    padding-right: 50px !important;
}

@media only screen and (max-width: 425px) {
    #onetrust-banner-sdk #onetrust-policy-text {
        padding-left: 25px !important;
    }
}

#onetrust-banner-sdk #onetrust-policy-text a,
#onetrust-banner-sdk .ot-b-addl-desc a {
    font-weight: normal !important;
    text-decoration-thickness: 0.5px !important;
}

CommonData.PCCustomCSS:
/* LAST UPDATED: 2024-12-10 */
/* UPDATE HERE AND IN a24-rudderstack/onetrust/prefs-custom-css.css */

/* PREFERENCE CENTER ***********************************/
/* hide floating button */
#ot-sdk-btn-floating {
    display: none !important;
}


/* containers */
.onetrust-pc-dark-filter {
    backdrop-filter: blur(45px);
    background: rgba(0, 0, 0, 0.666);
}

#onetrust-pc-sdk {
    border-radius: 0 !important;
    box-shadow:
        2.8px 2.8px 2.2px rgba(0, 0, 0, 0.02),
        6.7px 6.7px 5.3px rgba(0, 0, 0, 0.028),
        12.5px 12.5px 10px rgba(0, 0, 0, 0.035),
        22.3px 22.3px 17.9px rgba(0, 0, 0, 0.042),
        41.8px 41.8px 33.4px rgba(0, 0, 0, 0.05),
        100px 100px 80px rgba(0, 0, 0, 0.07);
}

/* header */
#onetrust-pc-sdk .ot-pc-header {
    padding-top: 15px;
    border-bottom: none;
}

#onetrust-pc-sdk .ot-title-cntr {
    position: static !important;
    width: calc(100% - 32px);
    padding-left: 32px;
    padding-top: 32px;
    padding-bottom: 20px;
}

@media (max-width: 640px) {
    #onetrust-pc-sdk .ot-title-cntr {
        padding-left: 20px;
    }
}

#onetrust-pc-sdk .ot-pc-logo.ot-pc-logo {
    display: none;
}

#onetrust-pc-sdk #ot-pc-title {
    text-transform: uppercase;
    font-size: 1.666em;
}

#onetrust-pc-sdk #ot-pc-title {
    color: #fff !important;
}

#onetrust-pc-sdk .ot-close-cntr {
    top: 0;
    right: 0;
    transform: none;
}

/* menu */
#onetrust-pc-sdk .category-menu-switch-handler {
    border-bottom-color: #222;
    border-left-width: 1px;
    padding-left: 41px;
    padding-top: 15px;
    padding-bottom: 15px;
}

@media (max-width: 640px) {
    #onetrust-pc-sdk .category-menu-switch-handler {
        padding-left: 19px;
    }
}

#onetrust-pc-sdk .category-menu-switch-handler h3 {
    text-transform: uppercase;
    line-height: 1;
}

#onetrust-pc-sdk .category-menu-switch-handler.ot-active-menu h3 {
    color: #fff !important;
}

@media (min-width: 550px) {
    #onetrust-pc-sdk .ot-tab-list {
        border-right: 1px solid #222;
        padding-top: 1px;
    }
}

/* content area */
#onetrust-pc-sdk .ot-desc-cntr {
    margin-top: 4px;
    padding-right: 32px;
    border-radius: 0;
}

@media (max-width: 640px) {
    #onetrust-pc-sdk .ot-desc-cntr {
        padding-right: 0;
    }
}

#onetrust-pc-sdk .ot-desc-cntr h4 {
    color: #fff !important;
    text-transform: uppercase;
}

#onetrust-pc-sdk #ot-pvcy-hdr {
    margin-top: 10px;
}

/* text */
#onetrust-pc-sdk strong {
    font-weight: 600 !important;
}

#onetrust-pc-sdk .ot-grp-desc {
    line-height: 1.3;
    font-size: 0.875em;
}

/* switches */
#onetrust-pc-sdk .ot-switch-nob {
    background-color: #666;
}

#onetrust-pc-sdk .ot-switch-nob:before {
    background: #ccc;
    box-shadow: 1px 2px 11px rgba(0, 0, 0, 0.666);
}

#onetrust-pc-sdk .ot-tgl input:checked+.ot-switch .ot-switch-nob {
    background: rgba(176, 233, 172, .333);
}

#onetrust-pc-sdk .ot-tgl input:checked+.ot-switch .ot-switch-nob:before {
    background: #b0e9ac;
}

#onetrust-pc-sdk .ot-always-active {
    color: #b0e9ac;
}

/* footer */
#onetrust-pc-sdk .ot-pc-footer {
    border-top: none;
}

#onetrust-pc-sdk .ot-pc-footer-logo {
    display: none;
}

#onetrust-pc-sdk .ot-pc-footer .ot-btn-container {
    display: flex;
}

@media (max-width: 640px) {
    #onetrust-pc-sdk .ot-pc-footer .ot-btn-container {
        flex-direction: column;
    }
}

#onetrust-pc-sdk .ot-pc-footer .ot-btn-container .ot-btn-subcntr {
    display: flex;
    flex: 1;
    float: none;
}

@media (max-width: 640px) {
    #onetrust-pc-sdk .ot-pc-footer .ot-btn-container .ot-btn-subcntr {
        flex-direction: column;
    }
}

/* footer buttons */
#onetrust-pc-sdk .ot-pc-footer button {
    line-height: 1;
    padding: 30px 42px;
    margin: 0 !important;
    font-size: 1.2em !important;
    font-weight: 600 !important;
    border: none !important;
}

@media (max-width: 640px) {
    #onetrust-pc-sdk .ot-pc-footer button {
        width: 100% !important;
    }
}

#onetrust-pc-sdk .ot-pc-footer #accept-recommended-btn-handler {
    flex: 1;
}

#onetrust-pc-sdk .ot-pc-footer #accept-recommended-btn-handler[aria-hidden=true] {
    display: block !important;
    opacity: 0.333;
    pointer-events: none;
}

#onetrust-pc-sdk .ot-pc-footer .save-preference-btn-handler {
    color: #b0e9ac !important;
    background: rgba(176, 233, 172, .18) !important;
}

#onetrust-pc-sdk .ot-pc-footer .save-preference-btn-handler:hover,
#onetrust-pc-sdk .ot-pc-footer .save-preference-btn-handler:active {
    color: #000 !important;
    background: rgba(176, 233, 172, .85) !important;
    opacity: 1 !important;
}

#onetrust-pc-sdk .ot-pc-footer .ot-pc-refuse-all-handler {
    color: #f95936 !important;
    background: rgba(249, 89, 54, .15) !important;
}

#onetrust-pc-sdk .ot-pc-footer .ot-pc-refuse-all-handler:hover,
#onetrust-pc-sdk .ot-pc-footer .ot-pc-refuse-all-handler:active {
    color: #000 !important;
    background: #f95936 !important;
    opacity: 1 !important;
}
